SELECT
WHERE a.deleted = 0
ORDER BY a.expect_start DESC, a.id DESC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE psyche_appointment
SET status = 'confirmed', confirmed_at = #{confirmedAt}, confirmed_by = #{confirmedBy}, updated_at = NOW()
WHERE id = #{id} AND deleted = 0 AND status = #{fromStatus}

UPDATE psyche_appointment
SET status = 'done', finished_at = #{finishedAt}, updated_at = NOW()
WHERE id = #{id} AND deleted = 0 AND status = #{fromStatus}

UPDATE psyche_appointment
SET status = 'cancelled', cancel_reason = #{cancelReason}, updated_at = NOW()
WHERE id = #{id} AND deleted = 0 AND status = #{fromStatus}
